import fs from 'node:fs';
import path from 'node:path';
const out = '/tmp/jstack-runtime-forensics-20261016/output';
const plan = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const log = fs.openSync(path.join(out, plan.name + '-protocol.jsonl'), 'a');
const socket = new WebSocket(fs.readFileSync(path.join(out, 'inspector-url.txt'), 'utf8'));
const pending = new Map();
let nextId = 0;
function record(direction, payload) { fs.writeSync(log, JSON.stringify({time: Date.now(), direction, payload})+'\n'); }
socket.addEventListener('message', event => {
  const payload = JSON.parse(event.data);
  record('receive', payload);
  if (payload.id && pending.has(payload.id)) {
    const {resolve, reject, timer} = pending.get(payload.id);
    clearTimeout(timer); pending.delete(payload.id);
    if (payload.error) reject(new Error(JSON.stringify(payload.error))); else resolve(payload.result);
  }
});
await new Promise((resolve, reject) => { socket.addEventListener('open', resolve, {once:true}); socket.addEventListener('error', reject, {once:true}); });
async function request(method, params = {}) {
  const id = ++nextId;
  const response = new Promise((resolve, reject) => {
    const timer = setTimeout(() => {pending.delete(id); reject(new Error('Timeout '+method));}, 8000);
    pending.set(id, {resolve, reject, timer});
  });
  const payload = {id, method, params}; record('send', payload); socket.send(JSON.stringify(payload));
  return await response;
}
try {
  for (const action of plan.actions) {
    if (action.delayMs) { await new Promise(resolve => setTimeout(resolve, action.delayMs)); continue; }
    const result = await request(action.method, action.params);
    if (action.save) fs.writeFileSync(path.join(out, action.save), JSON.stringify(result, null, 2));
    if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails));
  }
} catch (error) {
  fs.writeFileSync(path.join(out, plan.name + '-failure.txt'), error.stack);
  process.exitCode = 1;
} finally {
  socket.close();
  await new Promise(resolve => {socket.addEventListener('close', resolve, {once:true}); setTimeout(resolve, 1000);});
  fs.closeSync(log);
}

