{
  "scriptSource": "const readline = require('node:readline');
const { performance } = require('node:perf_hooks');

if (!process.stdin.isTTY) throw new Error('Run this app in a terminal');
globalThis.preview = { enabled: true, frames: 0, userEvents: 0, checksum: 0 };

function refreshPreview() {
  if (!preview.enabled) return;
  const stop = performance.now() + 6;
  let score = 0;
  while (performance.now() < stop) {
    for (let i = 0; i < 1000; i++) score = (score + i) % 9973;
  }
  preview.frames += 1;
  preview.checksum = score;
}

const timer = setInterval(refreshPreview, 20);
const terminal = readline.createInterface({ input: process.stdin, output: process.stdout });
console.log('Preview console ready. Commands: status, quit');
terminal.on('line', command => {
  preview.userEvents += 1;
  if (command === 'status') console.log(JSON.stringify(preview));
  else if (command === 'quit') {
    clearInterval(timer);
    terminal.close();
  } else console.log('Unknown command');
});
terminal.on('close', () => {
  clearInterval(timer);
  console.log('Preview console closed');
});
const watchdog = setTimeout(() => process.exit(9), 180000);
watchdog.unref();
"
}

